        else
            m_wack_sync <= {m_wack_sync[1:0], m_wack};
    end
    assign s_wack_sync = m_wack_sync[2];

    // ========================================================================
    // CDC Synchronization: B channel (m -> s)
    // ========================================================================

    // Request: m -> s
    reg [2:0] m_breq_sync;
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            m_breq_sync <= 3'b000;
        else
            m_breq_sync <= {m_breq_sync[1:0], m_breq};
    end
    assign s_breq_sync = m_breq_sync[2];

    // Acknowledge: s -> m
    reg [2:0] s_back_sync;
    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst)
            s_back_sync <= 3'b000;
        else
            s_back_sync <= {s_back_sync[1:0], s_back};
    end
    assign m_back_sync = s_back_sync[2];

    // ========================================================================
    // CDC Synchronization: AR channel (s -> m)
    // ========================================================================

    // Request: s -> m
    reg [2:0] s_arreq_sync;
    always @(posedge m_clk or posedge m_rst) begin
        if (m_rst)
