    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            m_arack_sync <= 3'b000;
        else
            m_arack_sync <= {m_arack_sync[1:0], m_arack};
    end
    assign s_arack_sync = m_arack_sync[2];

    // ========================================================================
    // CDC Synchronization: R channel (m -> s)
    // ========================================================================

    // Request: m -> s
    reg [2:0] m_rreq_sync;
    always @(posedge s_clk or posedge s_rst) begin
        if (s_rst)
            m_rreq_sync <= 3'b000;
        else
            m_rreq_sync <= {m_rreq_sync[1:0], m_rreq};
